export function getAuthenticTrackGeometry(trackNameOrHint: string, totalDist?: number): RealCircuitDefinition | null {
  const lower = (trackNameOrHint || "").toLowerCase();

  // Match by explicit keywords
  if (lower.includes("redbull") || lower.includes("red bull") || lower.includes("spielberg") || lower.includes("austria") || lower.includes("rbr")) {
    return REAL_CIRCUITS.redbullring;
  }
  if (lower.includes("spa") || lower.includes("francorchamps")) {
    return REAL_CIRCUITS.spa;
  }
  if (lower.includes("monza") || lower.includes("rettifilo")) {
    return REAL_CIRCUITS.monza;
  }
  if (lower.includes("silverstone")) {
    return REAL_CIRCUITS.silverstone;
  }
  if (lower.includes("suzuka")) {
    return REAL_CIRCUITS.suzuka;
  }
  if (lower.includes("interlagos") || lower.includes("pace") || lower.includes("sao paulo") || lower.includes("brasil")) {
    return REAL_CIRCUITS.interlagos;
  }
  if (lower.includes("cota") || lower.includes("americas") || lower.includes("austin")) {
    return REAL_CIRCUITS.cota;
  }
  if (lower.includes("zandvoort")) {
    return REAL_CIRCUITS.zandvoort;
  }
  if (lower.includes("barcelona") || lower.includes("catalunya") || lower.includes("montmelo")) {
    return REAL_CIRCUITS.barcelona;
  }
  if (lower.includes("sebring")) {
    return REAL_CIRCUITS.sebring;
  }
  if (lower.includes("mosport") || lower.includes("canadian tire") || lower.includes("ctmp")) {
    return REAL_CIRCUITS.mosport;
  }
  if (lower.includes("brands hatch") || lower.includes("brandshatch") || lower.includes("brands")) {
    return REAL_CIRCUITS.brandshatch;
  }
  if (lower.includes("ledenon")) {
    return REAL_CIRCUITS.ledenon;
  }
  if (lower.includes("bark river") || lower.includes("barkriver")) {
    return REAL_CIRCUITS.barkriver;
  }

  // --- Real layouts added 2026-10-16 (OSM / TUMFTM) ---
  if (lower.includes("nordschleife") || lower.includes("schleife") || lower.includes("combined")) {
    return null; // 20.8km Schleife / combined layouts: no geometry, never distance-match
  }
  if (lower.includes("road america") || lower.includes("elkhart")) {
    return REAL_CIRCUITS.roadamerica;
  }
  if (lower.includes("road atlanta")) {
    return REAL_CIRCUITS.roadatlanta;
  }
  if (lower.includes("laguna")) {
    return REAL_CIRCUITS.lagunaseca;
  }
  if (lower.includes("barber")) {
    return REAL_CIRCUITS.barber;
  }
  if (lower.includes("lime rock")) {
    return REAL_CIRCUITS.limerock;
  }
  if (lower.includes("sonoma") && lower.includes("cup")) {
    return REAL_CIRCUITS.sonomacup;
  }
  if (lower.includes("donington") && lower.includes("national")) {
    return REAL_CIRCUITS.doningtonnational;
  }
  if (lower.includes("nurburgring") || lower.includes("nürburgring")) {
    return REAL_CIRCUITS.nurburgringgp;
  }
  if (lower.includes("imola")) {
    return REAL_CIRCUITS.imola;
  }
  if (lower.includes("mugello")) {
    return REAL_CIRCUITS.mugello;
  }
  if (lower.includes("portimao") || lower.includes("portimão") || lower.includes("algarve")) {
    return REAL_CIRCUITS.portimao;
  }
  if (lower.includes("assen")) {
    return REAL_CIRCUITS.assen;
  }
  if (lower.includes("fuji")) {
    return REAL_CIRCUITS.fuji;
  }
  if (lower.includes("okayama")) {
    return REAL_CIRCUITS.okayama;
  }
  if (lower.includes("hungaroring") || lower.includes("budapest")) {
    return REAL_CIRCUITS.hungaroring;
  }
  if (lower.includes("hockenheim")) {
    return REAL_CIRCUITS.hockenheim;
  }
  if (lower.includes("montreal") || lower.includes("gilles villeneuve") || lower.includes("villeneuve")) {
    return REAL_CIRCUITS.montreal;
  }
  if (lower.includes("sepang")) {
    return REAL_CIRCUITS.sepang;
  }
  if (lower.includes("shanghai")) {
    return REAL_CIRCUITS.shanghai;
  }
  if (lower.includes("yas marina") || lower.includes("abu dhabi")) {
    return REAL_CIRCUITS.yasmarina;
  }
  if (lower.includes("melbourne") || lower.includes("albert park")) {
    return REAL_CIRCUITS.melbourne;
  }
  if (lower.includes("hermanos") || lower.includes("rodriguez") || lower.includes("rodríguez") || lower.includes("mexico city")) {
    return REAL_CIRCUITS.mexicocity;
  }
  if (lower.includes("sakhir") || lower.includes("bahrain")) {
    return REAL_CIRCUITS.sakhir;
  }
  if (lower.includes("sochi")) {
    return REAL_CIRCUITS.sochi;
  }
  if (lower.includes("moscow raceway")) {
    return REAL_CIRCUITS.moscowraceway;
  }
  if (lower.includes("norisring")) {
    return REAL_CIRCUITS.norisring;
  }
  if (lower.includes("oschersleben")) {
    return REAL_CIRCUITS.oschersleben;
  }

  // Known tracks WITHOUT real geometry yet: never let the distance fallback
  // paint them onto a wrong circuit (VIR 5263m sits 0.3% from Mugello,
  // Misano 4226m 0.8% from Zandvoort, Mid-Ohio 3862m 1.4% from Brands Hatch).
  // These fall through to learned/reconstructed geometry instead.
  if (
    lower.includes("watkins") ||
    lower.includes("virginia") ||
    lower.includes("mid-ohio") || lower.includes("mid ohio") || lower.includes("midohio") ||
    lower.includes("bathurst") || lower.includes("mount panorama") ||
    lower.includes("belle isle") || lower.includes("detroit") ||
    lower.includes("paul ricard") || lower.includes("castellet") ||
    lower.includes("misano") ||
    lower.includes("jerez") ||
    lower.includes("daytona") ||
    lower.includes("indianapolis") ||
    lower.includes("donington") ||
    lower.includes("sonoma") ||
    lower.includes("charlotte") ||
    lower.includes("phillip island")
  ) {
    return null;
  }

  // Fallback match by lap distance: return the CLOSEST match within ~3% of official FIA length
  // (not the first match — fixes misfires like Sebring 6019 vs Silverstone 5891 at 2.13%,
  //  Mosport 3957 vs Brands Hatch 3916 at 1.04%, RBR 4318 vs Zandvoort 4259 at 1.37%)
  if (totalDist && totalDist > 1000) {
    let best: RealCircuitDefinition | null = null;
    let bestErr = Infinity;
    for (const c of Object.values(REAL_CIRCUITS)) {
      const err = Math.abs(c.officialDistance - totalDist) / c.officialDistance;
      if (err < 0.035 && err < bestErr) {
        best = c;
        bestErr = err;
      }
    }
    if (best) return best;
  }

  return null;
}
